function inRange(n, min, max) {
  return Number.isFinite(n) && n >= min && n <= max;
}

function pick(layers, key) {
  for (let i = layers.length - 1; i >= 0; i--) {
    if (key in layers[i]) return layers[i][key];
  }
  return undefined;
}

function isMissing(raw) {
  return raw === undefined || raw === null || raw === "";
}

function validateTimeout(raw) {
  if (raw === undefined || raw === "") return ["timeout invalid"];
  const n = Number(raw);
  const ok = Number.isFinite(n) && n >= 1000 && n <= 60000;
  return ok ? [] : ["timeout invalid"];
}

function collectErrors(env) {
  const errors = [];
  if (!env.PAYMENT_API_KEY) errors.push("PAYMENT_API_KEY missing");
  const raw = env.PAYMENT_TIMEOUT_MS;
  const n = raw === undefined || raw === "" ? NaN : Number(raw);
  if (!(Number.isFinite(n) && n >= 1000 && n <= 60000)) {
    errors.push("PAYMENT_TIMEOUT_MS invalid");
  }
  return errors;
}

function checkPool(poolSize, dbMax) {
  return poolSize <= dbMax - 10 ? null : "pool too large";
}
